async function loadDashboard(userId, signal) {
  const [profile, permissions, notifications] = await Promise.all([
    fetch(`/api/users/${userId}`, { signal }).then(r => r.json()),
    fetch(`/api/users/${userId}/permissions`, { signal }).then(r => r.json()),
    fetch(`/api/users/${userId}/notifications`, { signal }).then(r => r.json())
  ]);
  return { profile, permissions, notifications };
}

const urls = ['/api/a', '/api/b', '/api/c'];
const results = await Promise.allSettled(urls.map(u => fetch(u).then(r => r.json())));

const ok = results.filter(r => r.status === 'fulfilled').map(r => r.value);
const failed = results.filter(r => r.status === 'rejected').map(r => r.reason);
console.log(`${ok.length} succeeded, ${failed.length} failed`);

function timeout(ms) {
  return new Promise((_, reject) =>
    setTimeout(() => reject(new Error(`timeout ${ms}ms`)), ms)
  );
}

async function fetchWithTimeout(url, ms, signal) {
  return Promise.race([
    fetch(url, { signal }).then(r => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
    }),
    timeout(ms)
  ]);
}

